insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000050200','N5','Pagi sebelum bekerja','[毎日|まいにち]、[六時|ろくじ]に[起|お]きます。[七時|しちじ]に[朝|あさ]ご[飯|はん]を[食|た]べます。[八時|はちじ]に[家|いえ]を[出|で]ます。','Setiap hari saya bangun pukul enam, sarapan pukul tujuh, lalu keluar rumah pukul delapan.','Waktu dan rutinitas');
