insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N5','Waktu + に','Menandai waktu tertentu terjadinya suatu kegiatan.','Jam atau hari tertentu + に + verba','七時に起きます。 Saya bangun pukul tujuh.','Jam tertentu menerima に. Kata relatif seperti 今日 dan 明日 umumnya berdiri tanpa に.','Waktu dan rutinitas') on conflict(level,pattern) do nothing;
