insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000040200','N4','Jadwal bertemu yang baru','[友達|ともだち]と[駅|えき]で[三時|さんじ]に[会|あ]う[予定|よてい]でしたが、[仕事|しごと]が[長|なが]くなりました。[電話|でんわ]で[相談|そうだん]して、[四時|よじ]に[会|あ]うことにしました。','Saya berencana bertemu teman pukul tiga di stasiun, tetapi pekerjaan berlangsung lebih lama. Setelah berdiskusi lewat telepon, kami memutuskan bertemu pukul empat.','Janji dan rencana');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000040201','N4','Dengarkan · Jadwal bertemu yang baru','curriculum/n4-2.mp3','Janji dan rencana');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N4','～ことにする','Menyatakan keputusan yang diambil sendiri atau bersama.','Verba bentuk kamus atau ない + ことにする','歩いて行くことにしました。 Kami memutuskan pergi berjalan kaki.','Gunakan ことになる jika keputusan ditetapkan dari luar atau sebagai hasil keadaan.','Janji dan rencana') on conflict(level,pattern) do nothing;
