insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000040500','N4','Belajar sedikit demi sedikit','[忙|いそが]しいので、[一度|いちど]に[長|なが]い[時間|じかん]は[勉強|べんきょう]できません。そこで、[寝|ね]る[前|まえ]に[毎日|まいにち][十分|じゅっぷん]だけ[勉強|べんきょう]するようにしています。','Karena sibuk, saya tidak bisa belajar lama sekaligus. Karena itu saya berusaha belajar sepuluh menit setiap hari sebelum tidur.','Hobi dan kebiasaan');
