insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000030100','N3','Pemilahan sampah lingkungan','[市|し]は、ごみを[減|へ]らすため、プラスチックの[回収日|かいしゅうび]を[増|ふ]やす。[住民|じゅうみん]は[汚|よご]れを[落|お]とし、[透明|とうめい]な[袋|ふくろ]に[入|い]れて[出|だ]すことになった。','Untuk mengurangi sampah, kota menambah hari pengumpulan plastik. Warga diminta membersihkannya dan memasukkannya ke kantong transparan.','Lingkungan');
