insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000030500','N3','Perpustakaan keliling','バスを[使|つか]った[移動図書館|いどうとしょかん]が、[今月|こんげつ]から[山|やま]の[近|ちか]くの[地区|ちく]を[回|まわ]る。[本|ほん]を[借|か]りるには、[最初|さいしょ]に[利用登録|りようとうろく]をする[必要|ひつよう]がある。','Mulai bulan ini perpustakaan keliling berbasis bus mendatangi wilayah dekat pegunungan. Untuk meminjam buku, pengunjung perlu mendaftar terlebih dahulu.','Kegiatan warga');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000030501','N3','Dengarkan · Perpustakaan keliling','curriculum/n3-5.mp3','Kegiatan warga');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N3','～には','Menyatakan tujuan yang memerlukan syarat atau tindakan tertentu.','Verba kamus + には + syarat','本を借りるには登録が必要です。 Untuk meminjam buku, pendaftaran diperlukan.','Kalimat syarat mengikuti には. Bentuk てには tidak dipakai untuk pola ini.','Kegiatan warga') on conflict(level,pattern) do nothing;
