insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000030600','N3','Judul melalui media sosial','[見出|みだ]しだけを[読|よ]んで[記事|きじ]を[共有|きょうゆう]すると、[内容|ないよう]を[誤解|ごかい]することがある。[共有|きょうゆう]する[前|まえ]に、[記事|きじ]の[日付|ひづけ]と[情報源|じょうほうげん]も[確認|かくにん]したい。','Membagikan artikel setelah hanya membaca judul bisa menyebabkan salah paham. Sebelum membagikan, sebaiknya cek tanggal dan sumber informasi.','Informasi dan media');
