insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N3','～だけで','Menunjukkan bahwa suatu tindakan hanya didasarkan pada hal yang terbatas.','Nomina + だけで','見た目だけで判断しないでください。 Jangan menilai dari penampilan saja.','だけで menekankan dasar yang terbatas. だけに biasanya memberi alasan atau memperkuat akibat.','Informasi dan media') on conflict(level,pattern) do nothing;
