insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000020100','N2','Uji tarif bus terpadu','[市|し]は[乗|の]り[継|つ]ぎの[負担|ふたん]を[軽減|けいげん]するため、[一定|いってい][時間内|じかんない]の[乗|の]り[継|つ]ぎに[割引|わりびき]を[適用|てきよう]する。[実証実験|じっしょうじっけん]の[間|あいだ]は、[現金|げんきん]ではなく[交通系|こうつうけい]カードが[必要|ひつよう]だ。','Kota memberi diskon untuk pindah kendaraan dalam batas waktu tertentu. Selama uji coba, pengguna perlu kartu transportasi.','Transportasi publik');
