insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000020200','N2','Pemberitahuan tarif baru','[原材料費|げんざいりょうひ]の[上昇|じょうしょう]を[受|う]け、[食堂|しょくどう]は[来月|らいげつ]から[定食|ていしょく]の[価格|かかく]を[引|ひ]き[上|あ]げる。ただし、すでに[購入|こうにゅう]した[食券|しょっけん]については[追加料金|ついかりょうきん]なしで[使|つか]える。','Karena biaya bahan baku naik, harga paket makan naik bulan depan. Tiket makan yang sudah dibeli tetap bisa digunakan tanpa biaya tambahan.','Ekonomi sehari-hari');
