insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000020400','N2','Pendaftaran daring dan loket','[手続|てつづ]きを[簡素化|かんそか]するため、[申請|しんせい]をオンラインで[受|う]け[付|つ]けることになった。その[一方|いっぽう]、[機器|きき]の[操作|そうさ]に[不慣|ふな]れな[人|ひと]に[配慮|はいりょ]し、[窓口|まどぐち]も[当面|とうめん]は[維持|いじ]する。','Pendaftaran dipindahkan juga ke daring demi menyederhanakan prosedur. Loket tetap tersedia untuk sementara demi pengguna yang belum terbiasa dengan perangkat.','Layanan digital');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000020401','N2','Dengarkan · Pendaftaran daring dan loket','curriculum/n2-4.mp3','Layanan digital');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N2','～に配慮し','Menyatakan pertimbangan terhadap kebutuhan atau dampak pada pihak lain.','Nomina + に配慮して / に配慮し','利用者の安全に配慮して設計した。 Desain mempertimbangkan keamanan pengguna.','Pihak atau aspek yang dipertimbangkan diikuti に. Tindakan yang menanggapi pertimbangan biasanya muncul sesudahnya.','Layanan digital') on conflict(level,pattern) do nothing;
