insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000020500','N2','Pelatihan pegawai lapangan','[研修|けんしゅう]は[講義|こうぎ]だけにとどまらず、[実際|じっさい]の[現場|げんば]で[作業|さぎょう]を[体験|たいけん]する[時間|じかん]も[設|もう]ける。[受講者|じゅこうしゃ]は[作業後|さぎょうご]に、[気|き]づいた[改善点|かいぜんてん]を[報告書|ほうこくしょ]にまとめる。','Pelatihan meliputi kuliah dan praktik di lapangan. Seusai praktik, peserta menyusun laporan tentang hal-hal yang bisa diperbaiki.','Pekerjaan dan pelatihan');
