insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000020600','N2','Hasil survei pengunjung','[利用者数|りようしゃすう]は[前年|ぜんねん]より[増|ふ]えたものの、[調査期間|ちょうさきかん]に[特別展|とくべつてん]があった。[担当者|たんとうしゃ]は、[通常時|つうじょうじ]にも[増加|ぞうか]するかどうかは[不明|ふめい]だと[説明|せつめい]した。','Jumlah pengunjung naik dibanding tahun lalu, tetapi ada pameran khusus pada periode survei. Belum diketahui apakah kenaikan juga terjadi di kondisi biasa.','Statistik publik');
