insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000010100','N1','Konsultasi perubahan peraturan','[改定案|かいていあん]の[骨子|こっし]は[公表|こうひょう]されたが、[施行日|しこうび]はまだ[確定|かくてい]していない。[市|し]は[意見募集|いけんぼしゅう]で[得|え]た[指摘|してき]を[踏|ふ]まえ、[施行時期|しこうじき]を[含|ふく]めて[最終案|さいしゅうあん]を[練|ね]るとしている。','Garis besar revisi sudah diumumkan, tetapi tanggal berlakunya belum pasti. Kota akan menyusun rancangan final termasuk waktu pemberlakuan dengan mempertimbangkan masukan publik.','Kebijakan publik');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000010101','N1','Dengarkan · Konsultasi perubahan peraturan','curriculum/n1-1.mp3','Kebijakan publik');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N1','～を踏まえ','Mengambil keputusan atau membentuk penilaian dengan mempertimbangkan bukti atau keadaan.','Nomina + を踏まえ / を踏まえて','調査結果を踏まえ、方針を修正した。 Kebijakan direvisi dengan mempertimbangkan hasil survei.','を踏まえ menunjukkan bahwa bukti digunakan sebagai dasar pertimbangan. をよそに menyatakan bahwa keadaan tersebut diabaikan.','Kebijakan publik') on conflict(level,pattern) do nothing;
