insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000010200','N1','Evaluasi program pendampingan','[支援|しえん]の[効果|こうか]を[測|はか]るには、[成績|せいせき]の[変化|へんか]だけでは[十分|じゅうぶん]とは[言|い]えない。[担当者|たんとうしゃ]は[参加者|さんかしゃ]が[自|みずか]ら[学習計画|がくしゅうけいかく]を[立|た]てられるようになったかどうかも[検証|けんしょう]する。','Perubahan nilai saja belum cukup untuk mengukur dampak pendampingan. Tim juga akan memeriksa apakah peserta sudah mampu menyusun rencana belajar sendiri.','Pendidikan');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000010201','N1','Dengarkan · Evaluasi program pendampingan','curriculum/n1-2.mp3','Pendidikan');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N1','～のみならず','Memperluas bahasan kepada unsur tambahan dalam ragam formal.','Nomina atau bentuk biasa + のみならず','費用のみならず、時間も必要です。 Selain biaya, waktu juga diperlukan.','Pasangkan unsur tambahan dengan も. Bentuk だけ menutup cakupan, sedangkan のみならず memperluasnya.','Pendidikan') on conflict(level,pattern) do nothing;
