insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000010300','N1','Pembukaan arsip warga','[寄託|きたく]された[記録|きろく]の[公開|こうかい]にあたり、[資料館|しりょうかん]は[個人|こじん]の[特定|とくてい]につながる[箇所|かしょ]を[伏|ふ]せる。[記録|きろく]が[作|つく]られた[当時|とうじ]の[背景|はいけい]については、[別途|べっと][解説|かいせつ]を[添|そ]える。','Saat membuka arsip titipan, lembaga menutupi bagian yang bisa mengungkap identitas individu. Latar saat arsip dibuat dijelaskan dalam catatan terpisah.','Pelestarian budaya');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000010301','N1','Dengarkan · Pembukaan arsip warga','curriculum/n1-3.mp3','Pelestarian budaya');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N1','～にあたり','Menandai saat melakukan tindakan penting sebagai konteks persiapan.','Nomina atau verba kamus + にあたり','公開にあたり、関係者と協議した。 Menjelang publikasi, kami berunding dengan pihak terkait.','Gunakan untuk awal tindakan penting. Untuk rutinitas harian, ～とき lebih wajar.','Pelestarian budaya') on conflict(level,pattern) do nothing;
