insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000010400','N1','Membaca ringkasan survei','[公表|こうひょう]された[要約|ようやく]は、[回答者|かいとうしゃ]の[意向|いこう]を[簡潔|かんけつ]に[示|しめ]す。[一方|いっぽう]、[回答率|かいとうりつ]が[低|ひく]いため、その[結果|けっか]を[住民全体|じゅうみんぜんたい]の[総意|そうい]と[見|み]なすのは[早計|そうけい]だ。','Ringkasan itu menyajikan kehendak responden. Karena tingkat respons rendah, terlalu dini untuk menganggap hasilnya mewakili kehendak seluruh warga.','Kualitas informasi');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000010401','N1','Dengarkan · Membaca ringkasan survei','curriculum/n1-4.mp3','Kualitas informasi');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N1','～と見なす','Memperlakukan atau menilai sesuatu sebagai kategori tertentu.','Nomina + と見なす','期限後の提出は欠席扱いと見なす。 Pengumpulan setelah tenggat diperlakukan sebagai ketidakhadiran.','Objek yang dinilai diikuti を, sementara kategori hasil penilaian diikuti と.','Kualitas informasi') on conflict(level,pattern) do nothing;
