insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000010500','N1','Akses taman selama renovasi','[老朽化|ろうきゅうか]に[伴|ともな]う[改修|かいしゅう]は[避|さ]けられないが、[全面閉鎖|ぜんめんへいさ]では[周辺住民|しゅうへんじゅうみん]への[影響|えいきょう]が[大|おお]きい。そのため、[工事区画|こうじくかく]を[分|わ]け、[利用|りよう]できる[区域|くいき]を[段階的|だんかいてき]に[切|き]り[替|か]える。','Renovasi akibat bangunan menua tak terhindarkan, tetapi penutupan total berdampak besar bagi warga. Karena itu area kerja dibagi dan bagian yang bisa digunakan diganti secara bertahap.','Pembangunan kota');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000010501','N1','Dengarkan · Akses taman selama renovasi','curriculum/n1-5.mp3','Pembangunan kota');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N1','～に応じて','Menyatakan bahwa tindakan disesuaikan dengan perubahan keadaan.','Nomina + に応じて','進捗に応じて日程を見直す。 Jadwal ditinjau sesuai kemajuan.','Gunakan に応じて bila tindakan menyesuaikan keadaan. にもかかわらず menandai pertentangan dengan dugaan.','Pembangunan kota') on conflict(level,pattern) do nothing;
