insert into public.passages(id,level,title,body,translation,topic) values ('00000000-0000-4000-8300-000000010600','N1','Prosedur cadangan layanan','[障害|しょうがい]の[発生頻度|はっせいひんど]が[低|ひく]いからといって、[代替手段|だいたいしゅだん]の[整備|せいび]を[後回|あとまわ]しにするわけにはいかない。[担当部署|たんとうぶしょ]は、[停止|ていし]が[長引|ながび]く[場合|ばあい]に[備|そな]え、[紙|かみ]で[申請|しんせい]を[受|う]け[付|つ]ける[手順|てじゅん]を[確認|かくにん]した。','Meski gangguan jarang terjadi, menunda penyediaan cara alternatif tidak bisa dibenarkan. Tim meninjau prosedur penerimaan pengajuan kertas jika layanan terhenti lama.','Dunia kerja');
insert into public.listening(id,level,title,path,topic) values ('00000000-0000-4000-8300-000000010601','N1','Dengarkan · Prosedur cadangan layanan','curriculum/n1-6.mp3','Dunia kerja');
insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors,topic) values ('N1','～わけにはいかない','Menjelaskan bahwa keadaan atau tanggung jawab membuat tindakan tertentu tidak patut atau tidak mungkin diambil.','Verba bentuk kamus + わけにはいかない','事情を知った以上、放置するわけにはいかない。 Karena sudah tahu situasinya, masalah tidak bisa dibiarkan.','わけにはいかない menyatakan kendala situasi atau kewajiban sosial. Bentuk potensial negatif menyatakan ketidakmampuan secara umum.','Dunia kerja') on conflict(level,pattern) do nothing;
